SELECT DISTINCT

FROM t_knowledge_base kb
LEFT JOIN t_knowledge_share_scope kss
ON kb.id = kss.knowledge_base_id
AND kss.workspace_id = #{workspaceId}


        kb.project_id = #{project_id}


        and type = #{type}


        AND (
        kb.workspace_id = #{workspaceId}
        OR kb.share_scope = 'GLOBAL'
        OR (kb.share_scope = 'PARTIAL' AND kss.knowledge_base_id IS NOT NULL)
        )


        and status = #{status}


        and name like concat('%', #{name}, '%') ESCAPE '/'


        and knowledge_base_connection_id = #{connectionId}


        and kb.created_user_id = #{createUserId}


        AND kb.id IN

            #{id}



ORDER BY update_time desc

