SELECT

FROM t_knowledge_base kb
INNER JOIN t_knowledge_share_scope kss
ON kb.id = kss.knowledge_base_id
WHERE kb.share_scope = 'PARTIAL'
AND kss.workspace_id = #{workspaceId}
AND kb.workspace_id != #{workspaceId}

    and kb.type = #{type}

ORDER BY update_time desc

